-- ==========================================
-- CORE USERS & ROLES
-- ==========================================
CREATE TABLE IF NOT EXISTS users (
  id UUID REFERENCES auth.users NOT NULL PRIMARY KEY,
  role TEXT NOT NULL CHECK (role IN ('user', 'vendor', 'admin')) DEFAULT 'user',
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  campus_id TEXT,
  wallet_balance NUMERIC(10, 2) NOT NULL DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Ensure wallet_balance column exists on existing users table
ALTER TABLE IF EXISTS public.users ADD COLUMN IF NOT EXISTS wallet_balance NUMERIC(10, 2) NOT NULL DEFAULT 0;

-- ==========================================
-- VENDORS & DELIVERY INFRASTRUCTURE
-- ==========================================
CREATE TABLE IF NOT EXISTS vendors (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  owner_id UUID REFERENCES public.users(id) NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  is_open BOOLEAN DEFAULT true,
  image_url TEXT,
  status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected')) DEFAULT 'pending',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS campus_buildings (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  code TEXT,
  name TEXT NOT NULL,
  address TEXT,
  latitude DECIMAL(10,7),
