-- Drop existing policies to avoid conflicts
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN (SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public') LOOP
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', r.policyname, r.tablename);
    END LOOP;
END $$;

-- ==========================================
-- USER POLICIES
-- ==========================================
CREATE POLICY "Users can view own profile" ON public.users FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Users can update own profile" ON public.users FOR UPDATE USING (auth.uid() = id);

-- ==========================================
-- VENDOR POLICIES
-- ==========================================
CREATE POLICY "Public can view vendors" ON public.vendors FOR SELECT USING (true);
CREATE POLICY "Vendors can update own data" ON public.vendors FOR UPDATE USING (auth.uid() = owner_id);

-- ==========================================
-- MENU POLICIES
-- ==========================================
CREATE POLICY "Public can view menus" ON public.menus FOR SELECT USING (true);
CREATE POLICY "Vendors can manage their menus" ON public.menus FOR ALL USING (
  EXISTS (SELECT 1 FROM public.vendors WHERE vendors.id = menus.vendor_id AND vendors.owner_id = auth.uid())
);

-- ==========================================
-- MENU ITEM POLICIES
-- ==========================================
CREATE POLICY "Public can view menu items" ON public.menu_items FOR SELECT USING (true);
CREATE POLICY "Vendors can manage menu items" ON public.menu_items FOR ALL USING (
  EXISTS (
    SELECT 1 FROM public.menus 
    JOIN public.vendors ON vendors.id = menus.vendor_id
    WHERE menus.id = menu_items.menu_id AND vendors.owner_id = auth.uid()
  )
);

-- ==========================================
-- ORDER POLICIES
-- ==========================================
CREATE POLICY "Users can view own orders" ON public.orders FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own orders" ON public.orders FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Vendors can view their orders" ON public.orders FOR SELECT USING (
  EXISTS (SELECT 1 FROM public.vendors WHERE vendors.id = orders.vendor_id AND vendors.owner_id = auth.uid())
);
CREATE POLICY "Vendors can update their orders" ON public.orders FOR UPDATE USING (
  EXISTS (SELECT 1 FROM public.vendors WHERE vendors.id = orders.vendor_id AND vendors.owner_id = auth.uid())
);

-- ==========================================
-- ORDER ITEM POLICIES
-- ==========================================
CREATE POLICY "Users can insert own order items" ON public.order_items FOR INSERT WITH CHECK (
  EXISTS (
    SELECT 1
    FROM public.orders
    WHERE orders.id = order_items.order_id
      AND orders.user_id = auth.uid()
  )
);

CREATE POLICY "Users and vendors can view order items" ON public.order_items FOR SELECT USING (
  EXISTS (
    SELECT 1
    FROM public.orders
    WHERE orders.id = order_items.order_id
      AND (
        orders.user_id = auth.uid()
        OR EXISTS (
          SELECT 1
          FROM public.vendors
          WHERE vendors.id = orders.vendor_id AND vendors.owner_id = auth.uid()
        )
      )
  )
);

-- ==========================================
-- DELIVERY LOCATION POLICIES
-- ==========================================
CREATE POLICY "Vendors can upsert delivery locations" ON public.order_delivery_locations FOR ALL USING (
  EXISTS (
    SELECT 1 FROM public.orders
    JOIN public.vendors ON vendors.id = orders.vendor_id
    WHERE orders.id = order_delivery_locations.order_id AND vendors.owner_id = auth.uid()
  )
);

CREATE POLICY "Users can view delivery locations" ON public.order_delivery_locations FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.orders
    WHERE orders.id = order_delivery_locations.order_id AND orders.user_id = auth.uid()
  )
);

-- ==========================================
-- CAMPUS & DELIVERY ZONE POLICIES
-- ==========================================
CREATE POLICY "Public can view campus buildings" ON public.campus_buildings FOR SELECT USING (true);
CREATE POLICY "Public can view delivery zones" ON public.delivery_zones FOR SELECT USING (true);

-- ==========================================
-- CLASS SESSION POLICIES
-- ==========================================
CREATE POLICY "Users can manage own class sessions" ON public.class_sessions FOR ALL USING (auth.uid() = user_id);

-- ==========================================
-- CART POLICIES
-- ==========================================
CREATE POLICY "Users can view own cart" ON public.user_carts FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own cart" ON public.user_carts FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can update own cart" ON public.user_carts FOR UPDATE USING (auth.uid() = user_id);
CREATE POLICY "Users can delete own cart" ON public.user_carts FOR DELETE USING (auth.uid() = user_id);

-- ==========================================
-- PROMOTION POLICIES
-- ==========================================
CREATE POLICY "Public can view active promotions" ON public.promotions FOR SELECT USING (
  is_active = true AND (starts_at IS NULL OR starts_at <= now()) AND (ends_at IS NULL OR ends_at >= now())
);

-- ==========================================
-- NOTIFICATION POLICIES
-- ==========================================
CREATE POLICY "Users can view own notifications" ON public.notifications FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can update own notifications" ON public.notifications FOR UPDATE USING (auth.uid() = user_id);

-- ==========================================
-- DEVICE TOKEN POLICIES
-- ==========================================
CREATE POLICY "Users can manage own device tokens" ON public.device_tokens FOR ALL USING (auth.uid() = user_id);

-- ==========================================
-- PROMOTION REDEMPTION POLICIES
-- ==========================================
CREATE POLICY "Users can view own promo redemptions" ON public.promotion_redemptions FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own promo redemptions" ON public.promotion_redemptions FOR INSERT WITH CHECK (auth.uid() = user_id);

-- ==========================================
-- MEDIA ITEM POLICIES
-- ==========================================
CREATE POLICY "Vendors can manage their media" ON public.media_items FOR ALL USING (
  EXISTS (SELECT 1 FROM public.vendors WHERE vendors.id = media_items.vendor_id AND vendors.owner_id = auth.uid())
);
CREATE POLICY "Public can view active media" ON public.media_items FOR SELECT USING (is_active = true);

-- ==========================================
-- WALLET & TRANSACTION POLICIES
-- ==========================================
CREATE POLICY "Users can view own wallet transactions" ON public.wallet_transactions FOR SELECT USING (auth.uid() = user_id);

-- ==========================================
-- REFERRAL POLICIES
-- ==========================================
CREATE POLICY "Users can view own referral codes" ON public.referral_codes FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can view referral redemptions" ON public.referral_redemptions FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.referral_codes
    WHERE referral_codes.id = referral_redemptions.referral_code_id AND referral_codes.user_id = auth.uid()
  )
);

-- ==========================================
-- LOYALTY POLICIES
-- ==========================================
CREATE POLICY "Users can view own loyalty account" ON public.loyalty_accounts FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can view own loyalty events" ON public.loyalty_events FOR SELECT USING (auth.uid() = user_id);

-- ==========================================
-- SUBSCRIPTION POLICIES
-- ==========================================
CREATE POLICY "Users can view own subscriptions" ON public.subscriptions FOR SELECT USING (auth.uid() = user_id);

-- ==========================================
-- VENDOR WATCH POLICIES
-- ==========================================
CREATE POLICY "Users can manage own vendor watches" ON public.vendor_watches FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Public can view vendor watches" ON public.vendor_watches FOR SELECT USING (true);

-- ==========================================
-- GROUP ORDER POLICIES
-- ==========================================
CREATE POLICY "Users can view group orders they are in" ON public.group_orders FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.group_order_members
    WHERE group_order_members.group_order_id = group_orders.id AND group_order_members.user_id = auth.uid()
  ) OR host_user_id = auth.uid()
);

-- ==========================================
-- REFUND REQUEST POLICIES
-- ==========================================
CREATE POLICY "Users can view own refund requests" ON public.refund_requests FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can create refund requests" ON public.refund_requests FOR INSERT WITH CHECK (auth.uid() = user_id);

-- ==========================================
-- CHAT & SUPPORT POLICIES
-- ==========================================
CREATE POLICY "Users can view their chat rooms" ON public.chat_rooms FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.chat_room_participants
    WHERE chat_room_participants.room_id = chat_rooms.id AND chat_room_participants.user_id = auth.uid()
  )
);

CREATE POLICY "Users can view messages in their rooms" ON public.chat_messages FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM public.chat_room_participants
    WHERE chat_room_participants.room_id = chat_messages.room_id AND chat_room_participants.user_id = auth.uid()
  )
);

CREATE POLICY "Users can insert messages in their rooms" ON public.chat_messages FOR INSERT WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.chat_room_participants
    WHERE chat_room_participants.room_id = chat_messages.room_id AND chat_room_participants.user_id = auth.uid()
  ) AND sender_type = 'user'
);

CREATE POLICY "Users can view own support tickets" ON public.support_tickets FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can create support tickets" ON public.support_tickets FOR INSERT WITH CHECK (auth.uid() = user_id);

-- ==========================================
-- ACCOUNT DELETION POLICIES
-- ==========================================
CREATE POLICY "Users can view own deletion request" ON public.user_deletion_requests FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own deletion request" ON public.user_deletion_requests FOR ALL USING (auth.uid() = user_id);

-- ==========================================
-- ADMIN LOG POLICIES
-- ==========================================
-- Admin-only policies would be enforced at the backend level via RBAC checks
